CREATE TABLE invitation_schema (singleton INTEGER PRIMARY KEY CHECK(singleton=1), version INTEGER NOT NULL CHECK(version=3)) STRICT;CREATE TABLE invitation_phones (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, platform TEXT NOT NULL CHECK(platform IN ('apple','android')), secret_hash TEXT NOT NULL, token_digest TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation>0), created_at INTEGER NOT NULL, permission_granted INTEGER NOT NULL DEFAULT 0 CHECK(permission_granted IN (0,1)), resident_active INTEGER NOT NULL DEFAULT 0 CHECK(resident_active IN (0,1)), last_revision INTEGER NOT NULL DEFAULT 0 CHECK(last_revision>=0)) STRICT;CREATE INDEX invitation_phones_user ON invitation_phones(user_id,id);CREATE TABLE invitation_consents (id TEXT PRIMARY KEY, phone_id TEXT NOT NULL REFERENCES invitation_phones(id) ON DELETE CASCADE, receiver_id TEXT NOT NULL REFERENCES remote_receivers(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, grant_id TEXT, grant_hash TEXT, enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), transport TEXT NOT NULL CHECK(transport IN ('apns','fcm','android_resident')), generation INTEGER NOT NULL CHECK(generation>0), transport_generation INTEGER NOT NULL DEFAULT 0 CHECK(transport_generation>=0), broker_enrollment TEXT, broker_ticket TEXT, transport_status TEXT NOT NULL DEFAULT 'unavailable', transport_phone_generation INTEGER NOT NULL DEFAULT 0 CHECK(transport_phone_generation>=0), UNIQUE(phone_id,receiver_id)) STRICT;CREATE INDEX invitation_consents_user ON invitation_consents(user_id,id);CREATE TABLE invitation_events (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, enrollment_id TEXT NOT NULL REFERENCES invitation_consents(id) ON DELETE CASCADE, phone_id TEXT NOT NULL REFERENCES invitation_phones(id) ON DELETE CASCADE, receiver_id TEXT NOT NULL REFERENCES remote_receivers(id) ON DELETE CASCADE, foreground_id TEXT NOT NULL, grant_id TEXT NOT NULL, phone_generation INTEGER NOT NULL, consent_generation INTEGER NOT NULL, transport_generation INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, phase TEXT NOT NULL CHECK(phase IN ('admitted','attempted','cancelled')), outcome TEXT, revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0), UNIQUE(receiver_id,foreground_id,enrollment_id)) STRICT;CREATE UNIQUE INDEX invitation_events_revision ON invitation_events(phone_id,revision);CREATE INDEX invitation_events_user ON invitation_events(user_id,id);CREATE INDEX invitation_events_pending ON invitation_events(phase,expires_at,id);CREATE TABLE invitation_cooldowns (receiver_id TEXT NOT NULL REFERENCES remote_receivers(id) ON DELETE CASCADE, phone_id TEXT NOT NULL REFERENCES invitation_phones(id) ON DELETE CASCADE, last_admitted_at INTEGER NOT NULL, PRIMARY KEY(receiver_id,phone_id)) STRICT;CREATE TABLE invitation_broker_revocations (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, enrollment_id TEXT NOT NULL, generation INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0) STRICT;CREATE TRIGGER invitation_phone_rebind AFTER UPDATE OF token_digest ON invitation_phones BEGIN UPDATE invitation_consents SET enabled=0,generation=min(generation+1,9007199254740991),transport_phone_generation=0,transport_status='unavailable' WHERE phone_id=NEW.id AND user_id=NEW.user_id; END;CREATE TRIGGER invitation_consent_cleanup BEFORE DELETE ON invitation_consents WHEN OLD.broker_ticket IS NOT NULL BEGIN INSERT INTO invitation_broker_revocations(id,user_id,enrollment_id,generation,created_at,expires_at,attempts) VALUES(OLD.broker_ticket,OLD.user_id,CASE WHEN json_valid(OLD.broker_ticket) THEN coalesce(json_extract(OLD.broker_ticket,'$.ticket_id'),OLD.broker_ticket) ELSE OLD.broker_ticket END,OLD.transport_generation,0,9223372036854775807,0) ON CONFLICT(id) DO NOTHING; END;INSERT INTO invitation_schema VALUES(1,3);